dashboard.definition:
{
  "title": "Path Lines",
  "description": "Maps+ path lines: no splits, time-gap splits and styled path layers.",
  "dataSources": {
    "ds_in_track_id_viz_1": {
      "type": "ds.search",
      "name": "Vehicle ID choices map 1",
      "options": {
        "query": "| inputlookup go_track_trackspoints.csv | rex field=_time \"(?<date>^\\d+-\\d+-\\d+)\" | search $date_filter_viz_1$ | stats values(track_id) as track_id | mvexpand track_id | sort +track_id",
        "queryParameters": {
          "earliest": "-24h@h",
          "latest": "now"
        }
      }
    },
    "ds_in_date_filter_viz_1": {
      "type": "ds.search",
      "name": "Date choices map 1",
      "options": {
        "query": "| inputlookup go_track_trackspoints.csv | lookup go_track_tracks.csv id as track_id | search $track_id_viz_1$ | rex field=_time \"(?<date>^\\d+-\\d+-\\d+)\" | stats values(date) as day | mvexpand day",
        "queryParameters": {
          "earliest": "-24h@h",
          "latest": "now"
        }
      }
    },
    "ds_in_track_id_viz_2": {
      "type": "ds.search",
      "name": "Vehicle ID choices map 2",
      "options": {
        "query": "| inputlookup go_track_trackspoints.csv | rex field=_time \"(?<date>^\\d+-\\d+-\\d+)\" | search $date_filter_viz_2$ | stats values(track_id) as track_id | mvexpand track_id | sort +track_id",
        "queryParameters": {
          "earliest": "-24h@h",
          "latest": "now"
        }
      }
    },
    "ds_in_date_filter_viz_2": {
      "type": "ds.search",
      "name": "Date choices map 2",
      "options": {
        "query": "| inputlookup go_track_trackspoints.csv | lookup go_track_tracks.csv id as track_id | search $track_id_viz_2$ | rex field=_time \"(?<date>^\\d+-\\d+-\\d+)\" | stats values(date) as day | mvexpand day",
        "queryParameters": {
          "earliest": "-24h@h",
          "latest": "now"
        }
      }
    },
    "ds_in_track_id_viz_3": {
      "type": "ds.search",
      "name": "Vehicle ID choices map 3",
      "options": {
        "query": "| inputlookup go_track_trackspoints.csv | rex field=_time \"(?<date>^\\d+-\\d+-\\d+)\" | search $date_filter_viz_3$ | stats values(track_id) as track_id | mvexpand track_id | sort +track_id",
        "queryParameters": {
          "earliest": "-24h@h",
          "latest": "now"
        }
      }
    },
    "ds_in_date_filter_viz_3": {
      "type": "ds.search",
      "name": "Date choices map 3",
      "options": {
        "query": "| inputlookup go_track_trackspoints.csv | lookup go_track_tracks.csv id as track_id | search $track_id_viz_3$ | rex field=_time \"(?<date>^\\d+-\\d+-\\d+)\" | stats values(date) as day | mvexpand day",
        "queryParameters": {
          "earliest": "-24h@h",
          "latest": "now"
        }
      }
    },
    "ds_map_1": {
      "type": "ds.search",
      "name": "Map 1 rows",
      "options": {
        "query": "| inputlookup go_track_trackspoints.csv | lookup go_track_tracks.csv id as track_id | rex field=_time \"(?<date>^\\d+-\\d+-\\d+)\" | search $date_filter_viz_1$ $track_id_viz_1$ | eval id=track_id, speed=round(speed, 2), vehicle_type=if(car_or_bus == 1, \"car\", \"bus\"), description=\"<table align=\\\"center\\\" border=\\\"1\\\"><tr><th>id</th><th>time</th><th>vehicle type</th><th>speed</th></tr><tr><td align=\\\"center\\\">\".id.\"</td><td align=\\\"center\\\">\"._time.\"</td><td align=\\\"center\\\">\".vehicle_type.\"</td><td>\".speed.\"</td></tr></table>\", tooltip=description",
        "queryParameters": {
          "earliest": "-24h@h",
          "latest": "now"
        }
      }
    },
    "ds_map_2": {
      "type": "ds.search",
      "name": "Map 2 rows",
      "options": {
        "query": "| inputlookup go_track_trackspoints.csv | lookup go_track_tracks.csv id as track_id | rex field=_time \"(?<date>^\\d+-\\d+-\\d+)\" | search $date_filter_viz_2$ $track_id_viz_2$ | eval id=track_id, speed=round(speed, 2), vehicle_type=if(car_or_bus == 1, \"car\", \"bus\"), description=\"<table align=\\\"center\\\" border=\\\"1\\\"><tr><th>id</th><th>time</th><th>vehicle type</th><th>speed</th></tr><tr><td align=\\\"center\\\">\".id.\"</td><td align=\\\"center\\\">\"._time.\"</td><td align=\\\"center\\\">\".vehicle_type.\"</td><td>\".speed.\"</td></tr></table>\", tooltip=description",
        "queryParameters": {
          "earliest": "-24h@h",
          "latest": "now"
        }
      }
    },
    "ds_map_3": {
      "type": "ds.search",
      "name": "Map 3 rows",
      "options": {
        "query": "| inputlookup go_track_trackspoints.csv | lookup go_track_tracks.csv id as track_id | rex field=_time \"(?<date>^\\d+-\\d+-\\d+)\" | search $date_filter_viz_3$ $track_id_viz_3$ | eval markerVisibility=\"hidden\", id=track_id, speed=round(speed, 2), vehicle_type=if(car_or_bus == 1, \"car\", \"bus\"), description=\"car \".id, tooltip=description, pathColor=case(like(id, \"16\"), \"#e50de5\"), pathWeight=case(like(id, \"16\"), \"20\"), pathOpacity=case(like(id, \"16\"), \"1.0\"), antPath=\"true\", layerDescription=case(like(pathLayer, \"cars-16-20\"), \"cars-16-20\", like(pathLayer, \"cars-17-22-23\"), \"cars-17-22-23\"), pathLayer=case(like(id, \"16\"), \"cars-16-20\", like(id, \"17\"), \"cars-17-22-23\", like(id, \"20\"), \"cars-16-20\", like(id, \"22\"), \"cars-17-22-23\", like(id, \"23\"), \"cars-17-22-23\"), layerPriority=case(like(pathLayer, \"cars-16-20\"), 10, like(pathLayer, \"cars-17-22-23\"), 5)",
        "queryParameters": {
          "earliest": "-24h@h",
          "latest": "now"
        }
      }
    }
  },
  "inputs": {
    "input_track_id_viz_1": {
      "type": "input.multiselect",
      "title": "Vehicle ID (map 1)",
      "options": {
        "token": "track_id_viz_1",
        "defaultValue": "*",
        "items": [
          {
            "label": "All",
            "value": "*"
          }
        ]
      },
      "dataSources": {
        "primary": "ds_in_track_id_viz_1"
      },
      "encoding": {
        "label": "primary.track_id",
        "value": "primary.track_id"
      }
    },
    "input_date_filter_viz_1": {
      "type": "input.multiselect",
      "title": "Date (map 1)",
      "options": {
        "token": "date_filter_viz_1",
        "defaultValue": "*",
        "items": [
          {
            "label": "All",
            "value": "*"
          }
        ],
        "isCascadingInput": true
      },
      "dataSources": {
        "primary": "ds_in_date_filter_viz_1"
      },
      "encoding": {
        "label": "primary.day",
        "value": "primary.day"
      }
    },
    "input_track_id_viz_2": {
