      "options": {
        "token": "date_filter_viz_2",
        "defaultValue": "2014-09-17",
        "items": [
          {
            "label": "All",
            "value": "*"
          }
        ],
        "isCascadingInput": true
      },
      "dataSources": {
        "primary": "ds_in_date_filter_viz_2"
      },
      "encoding": {
        "label": "primary.day",
